"""PILOTO DEL CORPUS · cuanto cuesta el tronco con T=256 y vocabulario abierto · 2026-09-11

Pregunta de Maxi: entrenar el micro-LM con un corpus real (TinyStories en castellano,
robrenaud/multilingual_tinystories). Antes de escribir un prereg hay que saber DOS numeros que
nadie midio: (1) s/paso y memoria pico del tronco de regla delta con T=256 y cabeza de 4-8k tokens
en una T4, porque el scan guarda el estado D x D por paso de tiempo para el backward y a T=256
puede no entrar; (2) cuantos tokens BPE tiene un cuento, para saber si T=256 alcanza.

Autocontenido: lleva `modelo.py` adentro (base64) y se corre con `colab run --gpu T4`. Cada
configuracion corre en un SUBPROCESO para que el pico de memoria sea suyo y un OOM no tumbe el resto.

    colab --auth adc run --gpu T4 --timeout 3600 piloto_corpus.py
"""
import base64, json, os, subprocess, sys, time

MODELO_B64 = ""
# `colab run` ejecuta esto como una celda de IPython: no hay __file__, asi que todo lo que un
# subproceso necesite se escribe a disco desde strings.
AQUI = "/content" if os.path.isdir("/content") else os.getcwd()
os.chdir(AQUI)
open("modelo.py", "wb").write(base64.b64decode(MODELO_B64))
WORKER = 'import json, os, sys, time\ndef medir(T, V, N, B, remat, D, NB):\n    os.environ["XLA_PYTHON_CLIENT_PREALLOCATE"] = "false"\n    import numpy as np\n    import jax, jax.numpy as jnp, optax\n    jax.config.update("jax_default_matmul_precision", "highest")\n    import modelo as M\n    M.KQ = 5\n    if remat:\n        M.delta_mixer = jax.checkpoint(M.delta_mixer)\n    params = M.init_params(0, V, D=D, NB=NB, N_TURNOS=64)\n    n_par = M.contar(params)\n    opt = optax.chain(optax.clip_by_global_norm(1.0), optax.adamw(1e-3, weight_decay=0.01))\n    state = opt.init(params)\n    rng = np.random.default_rng(0)\n    x = jnp.array(rng.integers(0, V, (B, T)))\n    if N:\n        archivo = jnp.array(rng.normal(size=(B, N, D)).astype(np.float32))\n        turnos = jnp.array(rng.integers(0, 64, (B, N)))\n        mask = jnp.ones((B, N), bool)\n\n    def perdida(p, x):\n        if N:\n            lg = M.responder(p, archivo, turnos, x, mask, donde="lat2")\n        else:\n            h = M.tronco(p, x)\n            lg = M.ln(p["ln_f"], h) @ p["head"]["w"] + p["head"]["b"]\n        return optax.softmax_cross_entropy_with_integer_labels(lg[:, :-1], x[:, 1:]).mean()\n\n    @jax.jit\n    def paso(p, s, x):\n        l, g = jax.value_and_grad(perdida)(p, x)\n        up, s = opt.update(g, s, p)\n        return optax.apply_updates(p, up), s, l\n\n    t0 = time.time()\n    params, state, l = paso(params, state, x); l.block_until_ready()\n    t_comp = time.time() - t0\n    ts = []\n    for _ in range(8):\n        t1 = time.time()\n        params, state, l = paso(params, state, x); l.block_until_ready()\n        ts.append(time.time() - t1)\n    st = jax.local_devices()[0].memory_stats() or {}\n    pico = st.get("peak_bytes_in_use", 0) / 2**30\n    return {"T": T, "V": V, "N": N, "B": B, "remat": remat, "D": D, "NB": NB, "params": n_par,\n            "s_paso": round(float(np.median(ts)), 4), "s_compila": round(t_comp, 1),\n            "pico_GiB": round(pico, 2), "tok_por_s": int(B * T / np.median(ts))}\n\n\n\nif __name__ == "__main__":\n    print(json.dumps(medir(*[int(v) for v in sys.argv[1].split(",")])))\n'
open("piloto_medir.py", "w", encoding="utf-8").write(WORKER)

SHARD = "https://huggingface.co/datasets/robrenaud/multilingual_tinystories/resolve/main/stories_00.json"

# (T, V, N_archivo, batch, remat, D, NB)
CONFIGS = [
    (48, 242, 40, 64, 0, 128, 4),      # referencia: el banco de hoy (0,46 s/paso en T4)
    (128, 4096, 40, 64, 0, 128, 4),
    (256, 4096, 0, 64, 0, 128, 4),
    (256, 4096, 40, 64, 0, 128, 4),
    (256, 8192, 40, 64, 0, 128, 4),
    (256, 4096, 40, 32, 0, 128, 4),
    (256, 4096, 40, 16, 0, 128, 4),
    (256, 4096, 40, 64, 1, 128, 4),    # remat del mixer: recomputa el scan en el backward
    (256, 4096, 3280, 64, 0, 128, 4),  # archivo largo + T largo
    (256, 4096, 40, 64, 0, 192, 6),    # el tamanio del LM del corpus
    (256, 4096, 40, 64, 1, 192, 6),
]


def tokenizador():
    """BPE chico sobre 100.000 cuentos reales: cuantos tokens tiene un cuento."""
    import urllib.request, re
    if not os.path.exists("stories_00.json"):
        print("bajando shard...", flush=True)
        t0 = time.time()
        def hook(n, bs, tot):
            if n % 200 == 0:
                print(f"  {n*bs/1e6:.0f} MB", flush=True)
        urllib.request.urlretrieve(SHARD, "stories_00.json", hook)
        print(f"  shard bajado en {time.time()-t0:.0f}s", flush=True)
    d = json.load(open("stories_00.json", encoding="utf-8"))
    cuentos = [r["story"] for r in d if r.get("story")]
    print(f"cuentos: {len(cuentos)}", flush=True)
    try:
        import tokenizers
    except ImportError:
        subprocess.run([sys.executable, "-m", "pip", "install", "-q", "tokenizers"], check=True)
        import tokenizers
    from tokenizers import Tokenizer, models, trainers, pre_tokenizers, normalizers
    import numpy as np
    out = {}
    for V in (2048, 4096, 8192):
        tok = Tokenizer(models.BPE(unk_token="[UNK]"))
        # minuscula + NFKC, por la leccion del 10-ago (los tokens capitalizados se colapsaban)
        tok.normalizer = normalizers.Sequence([normalizers.NFKC(), normalizers.Lowercase()])
        tok.pre_tokenizer = pre_tokenizers.Sequence([pre_tokenizers.Whitespace()])
        tr = trainers.BpeTrainer(vocab_size=V, special_tokens=["[UNK]", "[PAD]", "[BOS]", "[EOS]"],
                                 min_frequency=2, show_progress=False)
        t0 = time.time()
        tok.train_from_iterator(cuentos, trainer=tr)
        enc = tok.encode_batch(cuentos[:20000])
        L = np.array([len(e.ids) for e in enc])
        unk = sum(e.ids.count(0) for e in enc) / max(1, L.sum())
        out[V] = {"media": round(float(L.mean()), 1), "p50": int(np.median(L)),
                  "p90": int(np.percentile(L, 90)), "p95": int(np.percentile(L, 95)),
                  "p99": int(np.percentile(L, 99)), "max": int(L.max()),
                  "cabe_256": round(float((L <= 256).mean()), 4),
                  "cabe_384": round(float((L <= 384).mean()), 4),
                  "unk": round(float(unk), 6), "segundos": round(time.time() - t0, 1)}
        print(f"  BPE {V}: {out[V]}", flush=True)
        if V == 4096:
            print("  ejemplo:", tok.encode(cuentos[3][:200]).tokens[:40], flush=True)
    pal = np.array([len(re.findall(r"\w+", c)) for c in cuentos[:20000]])
    out["palabras"] = {"media": round(float(pal.mean()), 1), "p95": int(np.percentile(pal, 95))}
    return out


if __name__ == "__main__":
    try:
        hw = subprocess.run(["nvidia-smi", "--query-gpu=name,memory.total", "--format=csv,noheader"],
                            capture_output=True, text=True).stdout.strip()
    except OSError:
        hw = "sin nvidia-smi"
    res = {"hw": hw, "tronco": [], "bpe": None}
    print("GPU:", res["hw"], flush=True)
    for cfg in CONFIGS:
        arg = ",".join(str(v) for v in cfg)
        print(f"config {arg} ...", flush=True)
        r = subprocess.run([sys.executable, "piloto_medir.py", arg], capture_output=True, text=True)
        lineas = [l for l in r.stdout.splitlines() if l.startswith("{")]
        if r.returncode == 0 and lineas:
            fila = json.loads(lineas[-1])
        else:
            err = (r.stderr.strip().splitlines() or ["?"])[-1][:200]
            fila = {"T": cfg[0], "V": cfg[1], "N": cfg[2], "B": cfg[3], "remat": cfg[4], "D": cfg[5],
                    "NB": cfg[6], "error": err}
        print("  ->", fila, flush=True)
        res["tronco"].append(fila)
    try:
        res["bpe"] = tokenizador()
    except Exception as e:
        res["bpe"] = {"error": repr(e)[:300]}
        print("bpe fallo:", e, flush=True)
    print("@@JSON@@ " + json.dumps(res), flush=True)
